style.css:
@-moz-document domain("chat.openai.com"), domain("www.chat.openai.com") {
body {
    background-color: #ffe0f0 !important;
    background-image: url("https://i.imgur.com/QYk04Ct.png"); /* mini pink dino pattern */
    background-repeat: repeat;
    background-size: 60px 60px;
    font-family: "Comic Sans MS", cursive, sans-serif !important;
  }

  .bg-token-main-surface, .dark .bg-token-main-surface {
    background-color: rgba(255, 240, 250, 0.9) !important;
  }

  .text-base, .text-token-text-primary {
    color: #8b0057 !important;
  }

  .btn, .button, .text-sm, .text-md {
    background-color: #ff8acb !important;
    color: white !important;
    border-radius: 16px !important;
    border: 1px solid #ff3ca1 !important;
    box-shadow: 0px 2px 5px rgba(255, 105, 180, 0.4);
    transition: 0.3s ease-in-out;
  }

  .btn:hover, .button:hover {
    background-color: #ff3ca1 !important;
    transform: scale(1.05);
  }

  ::selection {
    background: #ffb6d1;
    color: white;
  }

  header, nav, .bg-token-main-nav, .dark .bg-token-main-nav {
    background-color: #ffcce5 !important;
  }

  /* Make message boxes slightly more bubbly */
  .rounded-md {
    border-radius: 20px !important;
  }
}
